var i=`0114-kama-dessert`;var t=`world-0114`;var a=`EE`;var n=`northern-europe`;var o=4;var s=39;var l={en:`Kama Dessert`,ua:`Десерт кама`};var u={en:`A classic dish from Estonia, featuring chickpea flour, kefir, blueberry. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Естонія. Основні складники: нутове борошно, кефір, лохина. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var h=[{en:`Mix barley, rye, oat and chickpea flours; these recreate a simplified version of roasted-grain kama flour.`,ua:`Змішайте ячмінне, житнє, вівсяне та нутове борошно, спрощену суміш для кама.`,t:[`mixing`],m:6,i:[[`barley-flour`,90,`g`],[`rye-flour`,90,`g`],[`oat-flour`,85,`g`],[`chickpea-flour`,55,`g`]]},{en:`Toast the flour mixture in a dry pan over low heat, stirring constantly, until fragrant and lightly browned. Cool fully.`,ua:`Прогрівайте суміш борошна на сухій сковороді на малому вогні, постійно помішуючи, до легкого підрум’янення й аромату. Повністю остудіть.`,t:[`dry-toasting`],m:8,i:[]},{en:`Whisk the toasted flour into kefir and honey, then serve with berries.`,ua:`Вмішайте підсмажене борошно в кефір із медом та подавайте з ягодами.`,t:[`whipping`],m:5,i:[[`kefir`,650,`ml`],[`honey`,75,`g`]]},{en:`Chill briefly if appropriate, garnish with the listed ingredients and serve at the intended temperature.`,ua:`За потреби недовго охолодіть, прикрасьте зазначеними складниками й подавайте за потрібної температури.`,t:[`garnishing`],m:20,i:[[`blueberry`,180,`g`]]}];var g={slug:i,id:t,country:`EE`,region:n,servings:4,minutes:39,title:l,text:u,steps:h};export{a as country,g as default,t as id,s as minutes,n as region,o as servings,i as slug,h as steps,u as text,l as title};